import ast

before = {
    "chat.py": "from retrieval import search\n",
    "retrieval.py": "from knowledge_store import lookup\n",
    "knowledge_store.py": "",
}
after = dict(before)
after["chat.py"] += "from telemetry import record_event\n"

def import_edges(files):
    edges = set()
    for name, source in files.items():
        tree = ast.parse(source or "pass", filename=name)
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.module:
                edges.add((name, node.module.split(".")[0]))
    return edges

old, new = import_edges(before), import_edges(after)
added, removed = new - old, old - new
expected_added = set()
unexpected = added - expected_added

assert added == {("chat.py", "telemetry")}
assert removed == set()
assert unexpected == {("chat.py", "telemetry")}
print("新增依赖:", sorted(added))
print("超出计划:", sorted(unexpected))
